#!/usr/bin/env node
// Verify the *published* CLI tarball, not merely the source checkout.
//
// The payload is generated by assemble-payload.mjs and npm's files filtering
// happens later. A source-level file list can therefore look correct while an
// end-user's installed package is missing a module. This check packs the
// already-assembled payload with lifecycle scripts disabled, then follows the
// relative import graph beginning at the staging entry point inside that
// tarball. It deliberately includes CommonJS requires: stage.mjs imports
// macos-signing.cjs that way.

import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { DESKTOP_RUNTIME_FILES } from "./payload-files.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const RUNTIME_ROOT = "package/payload/tools/desktop-runtime";
const STAGE_ENTRY = `${RUNTIME_ROOT}/stage.mjs`;
const npm = process.platform === "win32" ? "npm.cmd" : "npm";

function fail(message) {
  throw new Error(`packed-artifact-check: ${message}`);
}

function run(command, args, { encoding = "utf8", ...options } = {}) {
  const result = spawnSync(command, args, { encoding, ...options });
  if (result.error) fail(`${command}: ${result.error.message}`);
  if (result.status !== 0) {
    const detail = String(result.stderr || result.stdout || "").trim();
    fail(
      `${[command, ...args].join(" ")} exited ${result.status}${detail ? `: ${detail}` : ""}`,
    );
  }
  return result.stdout;
}

function readArgs(argv) {
  if (argv.length === 0) return null;
  if (argv.length === 2 && argv[0] === "--tarball") {
    return path.resolve(argv[1]);
  }
  fail("usage: node scripts/packed-artifact-check.mjs [--tarball path]");
}

function packArtifact(tempDir) {
  const payload = path.join(ROOT, "payload");
  if (!fs.existsSync(payload)) {
    fail(
      "payload/ is absent; run `npm run assemble` before checking the packed artifact",
    );
  }
  const output = run(
    npm,
    ["pack", "--ignore-scripts", "--json", "--pack-destination", tempDir],
    { cwd: ROOT },
  );
  let packed;
  try {
    packed = JSON.parse(output);
  } catch {
    fail(`npm pack returned invalid JSON: ${output}`);
  }
  if (!Array.isArray(packed) || packed.length !== 1 || !packed[0].filename) {
    fail(`npm pack returned an unexpected manifest: ${output}`);
  }
  return path.join(tempDir, packed[0].filename);
}

function tarEntries(tarball) {
  const output = run("tar", ["-tzf", tarball]);
  return new Set(output.split(/\r?\n/u).filter(Boolean));
}

function tarText(tarball, entry) {
  return run("tar", ["-xOf", tarball, entry]);
}

function assertNoTestFiles(entries) {
  const unexpected = [...entries].filter(
    (entry) =>
      /(?:^|\/)(?:tests?|__tests__)\//u.test(entry) ||
      /\/(?:test_[^/]+\.py|[^/]+\.(?:test|spec)\.[cm]?[jt]sx?)$/u.test(entry),
  );
  if (unexpected.length > 0) {
    fail(`test files were packed: ${unexpected.slice(0, 5).join(", ")}`);
  }
}

function relativeSpecifiers(source) {
  // These deliberately cover ESM static imports/re-exports, dynamic imports,
  // and CommonJS requires. Only literal relative specifiers can be proven at
  // package time; computed imports must be kept out of the runtime bootstrap.
  const patterns = [
    /\b(?:import|export)\s+(?:[\w*${},\s]*?\s+from\s+)?["'](\.{1,2}\/[^"']+)["']/gu,
    /\bimport\s*\(\s*["'](\.{1,2}\/[^"']+)["']\s*\)/gu,
    /\brequire\s*\(\s*["'](\.{1,2}\/[^"']+)["']\s*\)/gu,
  ];
  const imports = new Set();
  for (const pattern of patterns) {
    for (const match of source.matchAll(pattern)) imports.add(match[1]);
  }
  return imports;
}

function resolveImport(from, specifier, entries) {
  const candidate = path.posix.normalize(
    path.posix.join(path.posix.dirname(from), specifier),
  );
  if (candidate !== RUNTIME_ROOT && !candidate.startsWith(`${RUNTIME_ROOT}/`)) {
    fail(`${from} imports ${specifier}, which escapes ${RUNTIME_ROOT}`);
  }

  const extensions = path.posix.extname(candidate)
    ? [""]
    : ["", ".mjs", ".cjs", ".js", "/index.mjs", "/index.cjs", "/index.js"];
  const resolved = extensions
    .map((extension) => `${candidate}${extension}`)
    .find((file) => entries.has(file));
  if (!resolved)
    fail(`${from} imports ${specifier}, but no matching file is packed`);
  return resolved;
}

function assertRuntimeFiles(tarball, entries) {
  for (const file of DESKTOP_RUNTIME_FILES) {
    const entry = `${RUNTIME_ROOT}/${file}`;
    if (!entries.has(entry)) fail(`required runtime file is missing: ${entry}`);
  }

  const pending = [STAGE_ENTRY];
  const visited = new Set();
  while (pending.length > 0) {
    const current = pending.pop();
    if (visited.has(current)) continue;
    visited.add(current);

    if (!/\.(?:mjs|cjs|js)$/u.test(current)) continue;
    const source = tarText(tarball, current);
    for (const specifier of relativeSpecifiers(source)) {
      pending.push(resolveImport(current, specifier, entries));
    }
  }
  return visited;
}

const suppliedTarball = readArgs(process.argv.slice(2));
const tempDir = suppliedTarball
  ? null
  : fs.mkdtempSync(path.join(os.tmpdir(), "copilot-cli-pack-"));
try {
  const tarball = suppliedTarball ?? packArtifact(tempDir);
  if (!fs.existsSync(tarball)) fail(`tarball does not exist: ${tarball}`);
  const entries = tarEntries(tarball);
  assertNoTestFiles(entries);
  const files = assertRuntimeFiles(tarball, entries);
  console.log(
    `packed-artifact-check: OK (${path.basename(tarball)}; ${files.size} runtime module${files.size === 1 ? "" : "s"} verified)`,
  );
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
} finally {
  if (tempDir) fs.rmSync(tempDir, { recursive: true, force: true });
}
